const niches = [
  "restaurant in Pune",
  "clinic doctor in Pune",
  "CA chartered accountant in Pune",
  "gym fitness center in Pune",
  "salon beauty parlour in Pune",
  "coaching institute in Pune",
  "hotel guest house in Pune"
];
const dayIndex = new Date().getDay();
const search = niches[dayIndex % niches.length];
return [{ json: { search, max_results: 25, my_offer: "CodeRaksh Company builds AI-powered automation workflows that save your team 10+ hours every week — no coding needed, ready in days.", city: "Pune", niche_today: search } }];

return ($input.first().json.places || [])
  .filter(p => p.websiteUri)
  .map(p => ({ json: { business: p.displayName?.text, website: p.websiteUri, rating: p.rating, reviews: p.userRatingCount, address: p.formattedAddress, maps: p.googleMapsUri } }));

return $input.all().map((item, i) => {
  const biz = $('One row per business').all()[i].json;
  const html = String(item.json.data || '');
  const title = (html.match(/<title[^>]*>([^<]*)/i) || [])[1] || '';
  const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 2500);
  const signals = { has_whatsapp: /whatsapp/i.test(html), has_booking: /book (online|now)|appointment|schedule/i.test(html), has_chat: /intercom|tawk|crisp|livechat/i.test(html) };
  return { json: { ...biz, title, text, signals } };
});

